[{"id":"LA-001","category_id":"LA","ministry":"กระทรวงแรงงาน","title":"ประกาศกรมสวัสดิการและคุ้มครองแรงงาน เรื่อง แบบการแจ้งการดำเนินการหรือส่งเอกสารตามมาตรฐานในการบริหารและการจัดการด้านความปลอดภัยอาชีวอนามัย และสภาพแวดล้อมในการทำงานทางสื่ออิเล็กทรอนิกส์ พ.ศ.2553","summary":"การแจ้งการดำเนินการหรือส่งเอกสารต่ออธิบดี นายจ้างอาจแจ้งหรือส่งทางสื่ออิเล็กทรอนิกส์ ครอบคลุมแบบแจ้งรายละเอียดสารเคมีอันตราย แบบรายงานการฝึกซ้อมดับเพลิงและฝึกซ้อมหนีไฟ แบบรายงานผลการตรวจสุขภาพ","announced_date":"17 มีนาคม 2553","effective_date":"18 มีนาคม 2553","responsible_unit":"Safety","compliance_status":"C","check_frequency":"ตามกฎหมายกำหนด","reporting_channel":"ระบุไว้ใน PD การสื่อสาร","related_documents":null,"remarks":"บ.จัสเทล มีการขอ username & Password โดย HR","is_cancelled":false,"last_review_date":null,"review_period":null,"year":null,"created_at":"2026-06-03T04:01:14.971486+00:00","updated_at":"2026-06-03T04:01:14.971486+00:00"},{"id":"LA-002","category_id":"LA","ministry":"กระทรวงแรงงาน","title":"พระราชบัญญัติ ความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554","summary":"มาตรา 6: นายจ้างมีหน้าที่จัดและดูแลสถานประกอบกิจการให้มีสภาพการทำงานที่ปลอดภัย, มาตรา 8: บริหารจัดการความปลอดภัยตามมาตรฐานกฎกระทรวง, มาตรา 13: จัดให้มี จป. และขึ้นทะเบียน, มาตรา 16: ฝึกอบรมความปลอดภัย","announced_date":"2554","effective_date":"2554","responsible_unit":"จป.ทุกระดับ / Safety","compliance_status":"C","check_frequency":"สรุปเดือนละ 1 ครั้ง / ทบทวน 1 ครั้ง/ปี","reporting_channel":"ไซต์สื่อสาร Jastel Safety","related_documents":"F-255 แบบตรวจความปลอดภัย, นโยบายความปลอดภัย","remarks":null,"is_cancelled":false,"last_review_date":null,"review_period":null,"year":null,"created_at":"2026-06-03T04:01:14.971486+00:00","updated_at":"2026-06-03T04:01:14.971486+00:00"},{"id":"LA-003","category_id":"LA","ministry":"กระทรวงสาธารณสุข","title":"ประกาศคณะกรรมการการแพทย์ฉุกเฉิน เรื่อง กำหนดให้การใช้เครื่องฟื้นคืนคลื่นหัวใจด้วยไฟฟ้าแบบอัตโนมัติเป็นการปฐมพยาบาล พ.ศ. 2558","summary":"กำหนดให้การใช้เครื่อง AED (Automated External Defibrillator) เป็นการปฐมพยาบาล","announced_date":"22 เมษายน 2558","effective_date":"22 เมษายน 2558","responsible_unit":"Safety, Corporate Affair","compliance_status":"C","check_frequency":"ทุกรอบการประเมินกฎหมาย","reporting_channel":null,"related_documents":null,"remarks":"Office จัสเทล ชั้น 7 มีเครื่อง AED บริเวณหน้าห้องผู้บริหาร","is_cancelled":false,"last_review_date":null,"review_period":null,"year":null,"created_at":"2026-06-03T04:01:14.971486+00:00","updated_at":"2026-06-03T04:01:14.971486+00:00"},{"id":"LA-004","category_id":"LA","ministry":"กระทรวงแรงงาน","title":"ประกาศกรมสวัสดิการและคุ้มครองแรงงาน เรื่อง กำหนดแบบและวิธีการแจ้งการเกิดอุบัติภัยร้ายแรง หรือลูกจ้างประสบอันตรายจากการทำงาน ทางสื่ออิเล็กทรอนิกส์","summary":"การแจ้งการเกิดอุบัติภัยร้ายแรง หรือลูกจ้างประสบอันตรายจากการทำงาน นายจ้างอาจดำเนินการแจ้งหรือส่งโดยใช้แบบการแจ้งทางสื่ออิเล็กทรอนิกส์","announced_date":"2011-10-19","effective_date":"2011-10-19","responsible_unit":"Safety","compliance_status":"C","check_frequency":"เมื่อเกิดอุบัติเหตุร้ายแรง","reporting_channel":"สวัสดิการและคุ้มครองแรงงาน","related_documents":null,"remarks":"เมื่อเกิดอุบัติภัยสามารถส่งรายงานได้ทั้งทางอิเล็กทรอนิกส์และส่งที่สำนักงาน","is_cancelled":false,"last_review_date":null,"review_period":null,"year":null,"created_at":"2026-06-03T04:01:14.971486+00:00","updated_at":"2026-06-03T04:01:14.971486+00:00"},{"id":"LA-005","category_id":"LA","ministry":"กระทรวงสาธารณสุข","title":"กฎกระทรวง ควบคุมสถานประกอบกิจการที่เป็นอันตรายต่อสุขภาพ พ.ศ. 2560","summary":"อาคารต้องมีความมั่นคงแข็งแรง มีทางหนีไฟ บันไดหนีไฟ ทางออกฉุกเฉิน มีแสงสว่างเพียงพอ มีป้ายแสดงชัดเจน และมีมาตรการความปลอดภัยในการทำงาน","announced_date":"2017","effective_date":"2017","responsible_unit":"Premium Asset, SHE","compliance_status":"C","check_frequency":"ทุกรอบการประเมินกฎหมาย","reporting_channel":null,"related_documents":null,"remarks":null,"is_cancelled":false,"last_review_date":null,"review_period":null,"year":null,"created_at":"2026-06-03T04:01:14.971486+00:00","updated_at":"2026-06-03T04:01:14.971486+00:00"},{"id":"LA-006","category_id":"LA","ministry":"กระทรวงแรงงาน","title":"กฎกระทรวง กำหนดมาตรฐานเกี่ยวกับระบบการจัดการด้านความปลอดภัย พ.ศ. 2565","summary":"สถานประกอบกิจการที่มีลูกจ้าง 50 คนขึ้นไปต้องจัดให้มีระบบการจัดการความปลอดภัย ประกอบด้วย: 1.นโยบายความปลอดภัย 2.การจัดองค์กร 3.แผนงาน 4.การประเมินผล 5.การปรับปรุงพัฒนา","announced_date":"11 เมษายน 2565","effective_date":"11 มิถุนายน 2565","responsible_unit":"Safety, คปอ., ISO 45001","compliance_status":"C","check_frequency":"ทุกรอบการประเมินกฎหมาย","reporting_channel":null,"related_documents":null,"remarks":"บริษัทจัสเทล ดำเนินการขอรับรองระบบ ISO 45001","is_cancelled":false,"last_review_date":null,"review_period":null,"year":null,"created_at":"2026-06-03T04:01:14.971486+00:00","updated_at":"2026-06-03T04:01:14.971486+00:00"},{"id":"LA-007","category_id":"LA","ministry":"กระทรวงแรงงาน","title":"กฎกระทรวง การจัดให้มีเจ้าหน้าที่ความปลอดภัยในการทำงาน บุคลากร หน่วยงาน หรือคณะบุคคลเพื่อดำเนินการด้านความปลอดภัย พ.ศ. 2565","summary":"ข้อ 8: จป.ระดับหัวหน้างานต้องเป็นลูกจ้างระดับหัวหน้างาน, ข้อ 25: สถานประกอบกิจการที่มีลูกจ้าง 50 คนขึ้นไปต้องมีคณะกรรมการความปลอดภัย (คปอ.), ข้อ 42: ต้องนำรายชื่อ จป.ไปขึ้นทะเบียนภายใน 30 วัน","announced_date":"17 มิถุนายน 2565","effective_date":"17 สิงหาคม 2565","responsible_unit":"Safety","compliance_status":"C","check_frequency":"Annual","reporting_channel":null,"related_documents":"คู่มือว่าด้วยความปลอดภัย, ประกาศแต่งตั้ง จป.ทุกระดับ","remarks":null,"is_cancelled":false,"last_review_date":null,"review_period":null,"year":null,"created_at":"2026-06-03T04:01:14.971486+00:00","updated_at":"2026-06-03T04:01:14.971486+00:00"},{"id":"LA-009","category_id":"LA","ministry":"กระทรวงแรงงาน","title":"ประกาศกรมสวัสดิการและคุ้มครองแรงงาน เรื่อง การแจ้งการขึ้นทะเบียน การพ้นจากตำแหน่งหรือพ้นจากหน้าที่ของเจ้าหน้าที่ความปลอดภัยในการทำงาน","summary":"กำหนดให้นายจ้างต้องนำรายชื่อ จป. ทุกระดับ แจ้งการขึ้นทะเบียนหรือพ้นจากตำแหน่งต่อกรมสวัสดิการและค